use vstd::prelude::*;

verus! {

fn hermemulx(c: Vec<f64>) -> (result: Vec<f64>)
    requires
        c.len() < usize::MAX,
    ensures
        result.len() == c.len() + 1,
        result[0] == 0.0,
        forall|i: int|
            1 <= i && i < c.len() ==> result[i + 1] == c[i],
{
    let n: usize = c.len();

    // Build result of length n+1:
    // result[0] = 0.0
    // result[j] = c[j-1] for j >= 1
    let mut result: Vec<f64> = Vec::with_capacity(n + 1);
    result.push(0.0);

    let mut j: usize = 1;
    while j < n + 1
        invariant
            c.len() == n,
            n < usize::MAX,
            1 <= j && j <= n + 1,
            result.len() == j,
            result[0] == 0.0,
            forall|i: int|
                1 <= i && i < n && i + 1 < j as int ==> result[i + 1] == c[i],
        decreases (n + 1) - j
    {
        // Here j in [1, n], so j-1 is in [0, n-1] and is a valid index in c.
        result.push(c[j - 1]);
        j = j + 1;
    }

    result
}

} // verus!

